// Supabase Edge Function behind Settings → Integrations.
// handler.js is generated by `npm run build:api` from src/lib/integrations.
//
// Deploy it without the platform's JWT check: it checks each person's sign-in itself, and the
// browser's preflight request carries none.
//   supabase functions deploy integrations --no-verify-jwt
// It needs no secrets of its own: SUPABASE_URL, SUPABASE_ANON_KEY and SUPABASE_SERVICE_ROLE_KEY are
// provided by the platform. The service role reads the credentials kept in the vault.
import { createIntegrationsHandler } from "./handler.js";

declare const Deno: { env: { toObject(): Record<string, string> }; serve(handler: (request: Request) => Promise<Response>): void };

Deno.serve(createIntegrationsHandler(() => Deno.env.toObject()));
